#!/usr/bin/env python3
"""Compute ground truth for CSX-246_Q2 from the local CSX-246 event data."""

from __future__ import annotations

import json
import re
from datetime import datetime, timedelta
from html import unescape
from pathlib import Path
from typing import Any


TASK_ID = "CSX-246_Q2"
EVENT_ID = "CSX-246"
DIFFICULTY_LEVEL = "L2"

GDACS_PATH = "data/event_catalogs/event_catalogs_003_GDACS_earthquake_alert_API.json"
USGS_PATH = "data/event_reports/event_reports_001_Locked_anchor_USGS.html"
EVENT_PATH = "metadata/event.json"


def load_json(package_dir: Path, relative_path: str) -> dict[str, Any]:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def load_text(package_dir: Path, relative_path: str) -> str:
    return (package_dir / relative_path).read_text(encoding="utf-8", errors="replace")


def html_to_text(raw_html: str) -> str:
    text = re.sub(r"(?is)<(script|style).*?</\1>", " ", raw_html)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", unescape(text)).strip()


def parse_utc(timestamp: str) -> datetime:
    return datetime.fromisoformat(timestamp)


def severity(feature: dict[str, Any]) -> float:
    value = feature["properties"]["severitydata"]["severity"]
    return float(value)


def find_usgs_mainshock_magnitude(report_text: str) -> float:
    match = re.search(r"\bmagnitude\s+([0-9]+(?:\.[0-9]+)?)\s+Sumatra-Andaman", report_text, re.IGNORECASE)
    if not match:
        raise ValueError("USGS mainshock magnitude statement not found")
    return float(match.group(1))


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    event = load_json(package_dir, EVENT_PATH)
    gdacs = load_json(package_dir, GDACS_PATH)
    usgs_text = html_to_text(load_text(package_dir, USGS_PATH))
    usgs_mag = find_usgs_mainshock_magnitude(usgs_text)

    features = gdacs["features"]
    eq_features = [feature for feature in features if feature["properties"].get("eventtype") == "EQ"]
    fl_features = [feature for feature in features if feature["properties"].get("eventtype") == "FL"]
    eq_features_sorted = sorted(eq_features, key=lambda feature: feature["properties"]["fromdate"])

    red_eq = [
        feature
        for feature in eq_features
        if feature["properties"].get("alertlevel", "").lower() == "red"
        and feature["properties"].get("fromdate", "").startswith("2004-12-26")
    ]
    if len(red_eq) != 1:
        raise ValueError(f"Expected exactly one 2004-12-26 Red earthquake entry, found {len(red_eq)}")

    mainshock = red_eq[0]
    main_props = mainshock["properties"]
    main_time = parse_utc(main_props["fromdate"])
    main_mag = severity(mainshock)
    cutoff_72h = main_time + timedelta(hours=72)
    sequence_features = [
        feature
        for feature in features
        if parse_utc(feature["properties"]["fromdate"]) >= main_time
    ]
    sequence_fl_features = [
        feature for feature in sequence_features if feature["properties"].get("eventtype") == "FL"
    ]

    post_main = [
        feature
        for feature in eq_features
        if main_time < parse_utc(feature["properties"]["fromdate"]) <= cutoff_72h
    ]
    later_eq = [
        feature
        for feature in eq_features
        if parse_utc(feature["properties"]["fromdate"]) > main_time
    ]
    first_later_time = min(parse_utc(feature["properties"]["fromdate"]) for feature in later_eq)
    max_later_mag = max(severity(feature) for feature in later_eq)

    primary_gt = {
        "window_utc": f"{eq_features_sorted[0]['properties']['fromdate']}/{eq_features_sorted[-1]['properties']['fromdate']}",
        "feature_counts": {
            "total": len(sequence_features),
            "eq": len(eq_features),
            "fl": len(sequence_fl_features),
            "red_eq": sum(feature["properties"].get("alertlevel", "").lower() == "red" for feature in eq_features),
            "orange_eq": sum(feature["properties"].get("alertlevel", "").lower() == "orange" for feature in eq_features),
        },
        "threshold_counts": {
            "eq_mag_ge_6": sum(severity(feature) >= 6.0 for feature in eq_features),
            "post_main_eq_72h": len(post_main),
            "post_main_mag_ge_6_72h": sum(severity(feature) >= 6.0 for feature in post_main),
        },
        "mainshock": {
            "gdacs_eventid": int(main_props["eventid"]),
            "time_utc": main_props["fromdate"],
            "gdacs_mag": round(main_mag, 1),
            "usgs_mag": round(usgs_mag, 1),
        },
        "first_post_main_lag_min": round((first_later_time - main_time).total_seconds() / 60.0, 2),
        "max_post_main_mag": round(max_later_mag, 1),
        "mag_deltas": {
            "usgs_minus_gdacs_main": round(usgs_mag - main_mag, 1),
            "gdacs_main_minus_max_post": round(main_mag - max_later_mag, 1),
        },
        "conclusion": "passes_cross_source_catalog_ledger",
    }

    gates = {
        "has_single_red_eq_mainshock": primary_gt["feature_counts"]["red_eq"] == 1,
        "has_gdacs_eq_entries": primary_gt["feature_counts"]["eq"] == len(eq_features),
        "has_usgs_mainshock_crosscheck": primary_gt["mainshock"]["usgs_mag"] == 9.1,
        "has_nonempty_post_main_72h_window": primary_gt["threshold_counts"]["post_main_eq_72h"] > 0,
        "has_positive_mag_gap": primary_gt["mag_deltas"]["gdacs_main_minus_max_post"] > 0,
    }
    if not all(gates.values()):
        primary_gt["conclusion"] = "does_not_pass_cross_source_catalog_ledger"

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "earthquake_tsunami_catalog_sequence_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "catalog_window_hours": round(
                (parse_utc(eq_features_sorted[-1]["properties"]["fromdate"]) - parse_utc(eq_features_sorted[0]["properties"]["fromdate"])).total_seconds()
                / 3600.0,
                2,
            ),
            "post_main_cutoff_utc": cutoff_72h.isoformat(),
            "catalog_days_with_eq": sorted({feature["properties"]["fromdate"][:10] for feature in eq_features}),
            "gates": gates,
        },
        "tolerances": {
            "count_abs": 0,
            "magnitude_abs": 0.05,
            "magnitude_delta_abs": 0.05,
            "lag_minutes_abs": 0.01,
            "timestamp": "exact",
            "conclusion": "exact",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Returned JSON shape",
                    "points": 2,
                    "description": "Includes exactly the requested ledger fields with compact scalar or nested numeric values.",
                },
                {
                    "name": "Source filtering",
                    "points": 3,
                    "description": "Uses the GDACS event-list catalog for counts and timing, filters earthquake entries by eventtype, and uses the USGS anchor only for the 9.1 magnitude cross-check.",
                },
                {
                    "name": "Feature and threshold counts",
                    "points": 5,
                    "description": "Reports sequence total=11, eq=11, fl=0, red_eq=1, orange_eq=10, eq_mag_ge_6=4, post_main_eq_72h=9, and post_main_mag_ge_6_72h=3.",
                },
                {
                    "name": "Time-window reconstruction",
                    "points": 4,
                    "description": "Reports the correct earthquake timestamp window, mainshock timestamp, and 77.12 minute first-later-event lag.",
                },
                {
                    "name": "Magnitude consistency checks",
                    "points": 4,
                    "description": "Reports GDACS mainshock 8.5, USGS mainshock 9.1, max later GDACS severity 6.3, and deltas 0.6 and 2.2.",
                },
                {
                    "name": "Bounded answer discipline",
                    "points": 2,
                    "description": "Keeps the answer limited to catalog arithmetic and cross-source consistency fields.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                GDACS_PATH,
                USGS_PATH,
                EVENT_PATH,
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
